using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace Stackshot
{
    static class UiPaintingTests
    {
        static System.Collections.Generic.IEnumerable<Control> Children(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var c in Children(child))yield return c;}}
        [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr w,IntPtr l);
        internal static Bitmap NativePaint(Control control,Color initial){IntPtr handle=control.Handle;var image=new Bitmap(control.Width,control.Height,System.Drawing.Imaging.PixelFormat.Format24bppRgb);using(var g=Graphics.FromImage(image)){g.Clear(initial);IntPtr dc=g.GetHdc();try{SendMessage(handle,0x318,dc,new IntPtr(12));}finally{g.ReleaseHdc(dc);}}return image;}
        static string Hash(Bitmap image){using(var stream=new MemoryStream()){image.Save(stream,System.Drawing.Imaging.ImageFormat.Png);using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(stream.ToArray()));}}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("paint/tab changing glyph and selection erases every old pixel",delegate{using(var tab=new PreferencesTab{Text="OCR 与取色",Glyph="ocr"})using(var dirty=new Bitmap(tab.Width,tab.Height))using(var fresh=new Bitmap(tab.Width,tab.Height)){using(var g=Graphics.FromImage(dirty)){g.Clear(Color.Magenta);tab.Selected=true;tab.Glyph="gear";tab.PaintAt(g,tab.ClientRectangle);tab.Selected=false;tab.Glyph="ocr";tab.PaintAt(g,tab.ClientRectangle);}using(var g=Graphics.FromImage(fresh)){g.Clear(PreferencesLook.Header);tab.PaintAt(g,tab.ClientRectangle);}check(Hash(dirty)==Hash(fresh),"old selection or background survives repaint");}});
            run("paint/hidden native WM_PRINTCLIENT clears dirty background across repeated paints",delegate{using(var owner=new Form())using(var tab=new PreferencesTab{Text="快捷键",Glyph="keyboard"}){owner.Controls.Add(tab);var handle=owner.Handle;using(var first=NativePaint(tab,Color.Magenta))using(var second=NativePaint(tab,Color.Lime)){first.Save(Path.Combine(output,"tab-native-print.png"));check(Hash(first)==Hash(second),"native paint depends on old window pixels");}check(!owner.Visible&&!tab.Visible,"native print showed a window");}});
            run("paint/capture buttons own their entire background without native flat-button decorations",delegate{using(var button=new CaptureIconButton{Glyph="ellipse"}){var getStyle=typeof(Control).GetMethod("GetStyle",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);foreach(var style in new[]{ControlStyles.UserPaint,ControlStyles.AllPaintingInWmPaint,ControlStyles.OptimizedDoubleBuffer,ControlStyles.ResizeRedraw})check((bool)getStyle.Invoke(button,new object[]{style}),"capture button missing "+style);check(!button.UseVisualStyleBackColor,"native visual-style background remains");}});
            run("paint/capture icon native output equals authored output with clean perimeter",delegate{using(var owner=new Form())using(var button=new CaptureIconButton()){owner.Controls.Add(button);foreach(var glyph in new[]{"rect","ellipse","line","arrow","pen","text","counter","cloud","no-fill","fill","dash"})foreach(bool selected in new[]{false,true}){button.Glyph=glyph;button.Selected=selected;using(var printed=NativePaint(button,Color.Magenta))using(var expected=new Bitmap(button.Width,button.Height,System.Drawing.Imaging.PixelFormat.Format24bppRgb)){using(var g=Graphics.FromImage(expected)){g.Clear(CaptureLook.Surface);button.PaintButton(g,button.ClientRectangle);}if(Hash(printed)!=Hash(expected)){printed.Save(Path.Combine(output,"capture-button-native-mismatch.png"));expected.Save(Path.Combine(output,"capture-button-expected.png"));}check(Hash(printed)==Hash(expected),"native border or extra decoration on "+glyph);foreach(var p in new[]{new Point(0,0),new Point(0,button.Height/2),new Point(button.Width-1,button.Height/2),new Point(button.Width/2,0),new Point(button.Width/2,button.Height-1)})check(printed.GetPixel(p.X,p.Y).ToArgb()==CaptureLook.Surface.ToArgb(),"square edge on "+glyph+" selected="+selected+" at "+p+" color="+printed.GetPixel(p.X,p.Y));}}check(!owner.Visible,"capture test showed a window");}});
            run("paint/capture default selected hover and disabled share clean toolbar surface",delegate{using(var owner=new Form())using(var button=new CaptureIconButton())using(var sheet=new Bitmap(620,228)){owner.Controls.Add(button);using(var g=Graphics.FromImage(sheet))using(var font=new Font("Segoe UI",9)){g.Clear(CaptureLook.Surface);string[] labels={"Default","Selected","Hover","Disabled"},glyphs={"rect","ellipse","line","arrow","pen","text","counter","cloud","no-fill","fill","dash"};for(int row=0;row<4;row++){button.Selected=row==1;button.Enabled=row!=3;typeof(Control).GetMethod(row==2?"OnMouseEnter":"OnMouseLeave",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});g.DrawString(labels[row],font,Brushes.SlateGray,10,15+row*48);for(int i=0;i<glyphs.Length;i++){button.Glyph=glyphs[i];using(var printed=NativePaint(button,Color.Magenta)){foreach(var p in new[]{new Point(0,0),new Point(0,17),new Point(33,17),new Point(17,0),new Point(17,33)})check(printed.GetPixel(p.X,p.Y).ToArgb()==CaptureLook.Surface.ToArgb(),"state border residue "+labels[row]);g.DrawImageUnscaled(printed,110+i*44,8+row*48);}}}g.DrawString("HIDDEN HWND PAINT · SYNTHETIC FIXTURE · GUI NOT RUN",font,Brushes.Gray,10,207);}sheet.Save(Path.Combine(output,"capture-buttons-native-states.png"));check(!owner.Visible,"state test showed a window");}});
            run("paint/native settings controls remain isolated through one hundred glyph and state changes",delegate{using(var owner=new Form())using(var tab=new PreferencesTab{Text="工具栏",Glyph="rect"})using(var toggle=new PreferencesSwitch()){owner.Controls.Add(tab);owner.Controls.Add(toggle);var handle=owner.Handle;for(int i=0;i<100;i++){tab.Selected=i%2==0;tab.Glyph=i%3==0?"keyboard":"gear";toggle.Checked=i%2==0;using(var a=NativePaint(tab,Color.Black))using(var b=NativePaint(tab,Color.White))check(Hash(a)==Hash(b),"tab residue at "+i);using(var a=NativePaint(toggle,Color.Magenta))using(var b=NativePaint(toggle,Color.Lime))check(Hash(a)==Hash(b),"switch residue at "+i);}check(!owner.Visible,"showed a window");}});
            run("paint/native settings tabs render at 100 125 150 and 200 percent sizes",delegate{using(var sheet=new Bitmap(700,150)){using(var g=Graphics.FromImage(sheet)){g.Clear(PreferencesLook.Header);int x=0;foreach(float scale in new[]{1f,1.25f,1.5f,2f})using(var font=new Font("Microsoft YaHei UI",9*scale))using(var tab=new PreferencesTab{Text="OCR 与取色",Glyph="ocr",Selected=true,Font=font,Size=new Size((int)(96*scale),(int)(67*scale))}){using(var printed=NativePaint(tab,Color.Magenta)){check(printed.GetPixel(0,0).ToArgb()==PreferencesLook.Header.ToArgb(),"native corner residue");g.DrawImageUnscaled(printed,x,0);}x+=tab.Width+10;}}sheet.Save(Path.Combine(output,"tabs-native-dpi-sizes.png"));}});
            run("settings/native Windows caption replaces traffic lights and general page has no empty scroll",delegate{using(var dialog=new SettingsDialog(new Preferences(),"fixture",delegate{return "unused";})){check(dialog.FormBorderStyle==FormBorderStyle.Sizable&&dialog.ControlBox&&dialog.MinimizeBox&&dialog.MaximizeBox&&dialog.Region==null,"custom Mac window buttons remain");var body=Children(dialog).OfType<Panel>().Single(p=>p.Controls.OfType<Panel>().Count(c=>c.AutoScroll)==7);dialog.SelectPage(0);var page=body.Controls.OfType<Panel>().Single(p=>p.Controls.Cast<Control>().Any(c=>c.Text=="常规"));check(page.AutoScrollMinSize.Height<page.ClientSize.Height,"general page forces unnecessary scroll");using(var preview=dialog.RenderSyntheticPreview(0))preview.Save(Path.Combine(output,"settings-windows-client-offscreen.png"));check(!dialog.Visible,"settings shown");}});
            run("menu/styled tray retains daily commands and capture submenu and refreshes shortcut labels without registrations",delegate{var p=new Preferences();var actions=new System.Collections.Generic.List<string>();using(var menu=TrayActions.Create(delegate{return p;},actions.Add)){check(menu.Renderer is CraftMenuRenderer&&menu.Items.OfType<CraftMenuItem>().Count()==16,"unstyled menu or lost command");foreach(var item in menu.Items.OfType<CraftMenuItem>()){if(item.HasDropDownItems)foreach(ToolStripMenuItem child in item.DropDownItems)child.PerformClick();else item.PerformClick();}check(actions.SequenceEqual(new[]{"capture","fullscreen","window","repeat","ocr","color","scroll","open","files","paste","pins","memo","history","board","folder","togglepins","settings","exit"}),"wrong callback routing");p.Capture="Ctrl+Shift+F8";TrayActions.Refresh(menu,p);check(menu.Items.OfType<CraftMenuItem>().Single(i=>i.Name=="capture").ShortcutKeyDisplayString==p.Capture,"shortcut label stale");check(menu.Items.OfType<CraftMenuItem>().All(i=>i.ShortcutKeys==Keys.None)&&!menu.Visible,"registered a key or showed menu");}});
            run("menu/native popup paints icons shortcuts group dividers and selected row while hidden",delegate{using(var menu=TrayActions.Create(delegate{return new Preferences();},delegate{})){menu.Items.OfType<CraftMenuItem>().Single(i=>i.Name=="capture").Select();using(var image=menu.RenderOffscreen()){image.Save(Path.Combine(output,"tray-menu-native-offscreen.png"));int ink=0,blue=0;for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++){var c=image.GetPixel(x,y);if(c.R<145&&c.G<145&&c.B<145)ink++;if(c.B>160&&c.R<120)blue++;}check(ink>1000&&blue>20,"menu contents missing from native paint");}check(menu.Items.OfType<ToolStripSeparator>().Count()==2&&menu.Width>=290&&menu.Width<600&&!menu.Visible,"layout or desktop boundary");}});
            run("menu/pin context menu uses shared renderer and preserves checked and submenu semantics",delegate{using(var menu=TrayMenu.Create()){var command=TrayMenu.Item("复制图片","copy",delegate{});menu.Items.Add(command);var checkItem=new ToolStripMenuItem("置顶"){Checked=true,CheckOnClick=true};menu.Items.Add(checkItem);var opacity=new ToolStripMenuItem("透明度");opacity.DropDownItems.Add("80%");menu.Items.Add(opacity);((StyledMenu)menu).PrepareLayout();checkItem.PerformClick();check(menu.Renderer is CraftMenuRenderer&&!checkItem.Checked&&opacity.DropDown.Renderer is CraftMenuRenderer,"native check or submenu behavior lost");check(!menu.Visible,"pin menu shown");}});
        }
    }
}
